-- Spell icons: the class tabs (Shaman buff and totem tabs, Paladin seals and auras, Warrior stances) wear either
-- the game's own icon ("stock") or the same icon restyled live in the STUwave colours ("gradient", the default), chosen
-- by the setting `icons.spellstyle`.
--
-- The gradient style ships no art of the game's: the tile keeps drawing the game's own texture, and FS.IconStyle (see
-- there) stacks overlay textures over it (an ADD copy, a MOD ramp of ours, an ADD lift). Which icons get it, with which colour
-- family and brightness, is FS.IconStyleData.spells (generated by tools/assets/synthwave_icons.py --gen-runtime): the icon
-- FILE ID the client reports for a spell, or the lower case icon file name when it answers with an Interface\Icons path, to
-- an icon name, and `look` from that name to { fam, boost }. Anything not in the table keeps its stock texture, so a tile is
-- never blank: Look returns nil whenever it has nothing better.
--
-- Callers do not draw the texture themselves: FrameHelpers.SetSpellIcon(tex, stock) goes through Set, which writes the
-- texture, dresses it in the current style and remembers the stock icon per texture, so a change of the setting repaints every
-- bound texture at once. The tiles keep tinting, dimming, desaturating, showing and hiding their icon texture the way they
-- always did; the overlays follow it through post-hooks on those setters. Texture writes only; legal in combat, and a write
-- that errors is skipped.
local _, FS = ...

local SpellArt = {}
FS.SpellArt = SpellArt

SpellArt.SETTING = {
    key = "icons.spellstyle", default = "gradient", label = "Spell icons",
    tip = "Gradient draws the spell icons on the class tabs (Shaman buffs and totems, Paladin seals and auras, "
        .. "Warrior stances) in the STUwave colours. Stock shows the game's own icons.",
}
SpellArt.STYLES = { "gradient", "stock" }

if FS.Config and FS.Config.RegisterDefault then
    FS.Config.RegisterDefault(SpellArt.SETTING.key, SpellArt.SETTING.default)
end

-- "gradient" unless the setting says "stock"; any other value is the default.
function SpellArt.Style()
    local config = FS.Config
    local value = config and config.Get and config.Get(SpellArt.SETTING.key)
    if value == "stock" then return "stock" end
    return "gradient"
end

local function Spells()
    local data = FS.IconStyleData
    return data and data.spells
end

local function ArtName(stock)
    local spells = Spells()
    if not spells then return nil end
    if type(stock) == "number" then return spells.byFile[stock] end
    if type(stock) == "string" then
        local name = stock:lower():match("([^\\/]+)$")
        if name then return spells.byName[name:gsub("%.%a+$", "")] end
    end
    return nil
end

-- The icon values the client reported that have no look, each once, in the order first seen (capped), so a play
-- session shows which spells Forever draws with an id the table lacks. Kept in ForeverSTUwaveDB.buffTabEngine.unmappedIcons
-- (BuffTab's state table, on disk after a /reload) and carried across its rewrites by BuffTab's WriteStatus.
local UNMAPPED_CAP = 40
local unmapped, unmappedSeen = {}, {}

function SpellArt.UnmappedLine()
    if #unmapped == 0 then return nil end
    return table.concat(unmapped, ", ")
end

function SpellArt.UnmappedCount()
    return #unmapped
end

-- Written to the saved table whenever it can take it; an icon first seen while the database was read-only or not ready
-- stays pending (it is already in the list) and goes out with the next sighting of any unmapped icon.
local pending = false

local function Flush()
    -- never create or replace the database (Config leaves a corrupt or newer one alone on purpose)
    local db = ForeverSTUwaveDB
    if type(db) ~= "table" or (FS.Config and type(FS.Config.IsReadOnly) == "function" and FS.Config.IsReadOnly()) then return end
    if db.buffTabEngine == nil then db.buffTabEngine = {} end
    if type(db.buffTabEngine) ~= "table" then return end
    db.buffTabEngine.unmappedIcons = table.concat(unmapped, ", ")
    pending = false
end

local function NoteUnmapped(stock)
    if type(stock) ~= "number" and type(stock) ~= "string" then return end
    local key = tostring(stock)
    if not unmappedSeen[key] and #unmapped < UNMAPPED_CAP then
        unmappedSeen[key] = true
        unmapped[#unmapped + 1] = key
        pending = true
    end
    if pending then Flush() end
end

-- The look ({ fam, boost }) to dress the stock icon the client gave in, or nil: the style is stock, or nothing is known about
-- the icon (nil, a secret value and anything unknown included).
function SpellArt.Look(stock)
    if stock == nil or (FS.IsSecret and FS.IsSecret(stock)) then return nil end
    local name = ArtName(stock)
    if not name then
        pcall(NoteUnmapped, stock)
        return nil
    end
    if SpellArt.Style() ~= "gradient" then return nil end
    return Spells().look[name]
end

-- texture -> the stock texture it was last given. Weak keys: a dropped button frees its entry.
local bound = setmetatable({}, { __mode = "k" })

-- true once any tab has bound an icon: the settings page offers the choice only then.
function SpellArt.Applies()
    return next(bound) ~= nil
end

-- texture -> its chain of overlays (FS.IconStyle), built the first time the texture gets a look. Weak keys.
local chains = setmetatable({}, { __mode = "k" })

-- A tint with every channel at or above this is a plain white one.
local NEAR_WHITE = 0.98

-- What the texture wears now, read back from it, copied onto the overlays.
local function Mirror(chain)
    local tex = chain.base
    local r, g, b, a = tex:GetVertexColor()
    local alpha = (a or 1) * (tex:GetAlpha() or 1)
    -- a dimmed or tinted tile (the stance bar's 0.4, the buff tab's warn red): the MOD ramp would ignore it
    local dim = alpha < 1 or (r or 1) < NEAR_WHITE or (g or 1) < NEAR_WHITE or (b or 1) < NEAR_WHITE
    FS.IconStyle.Sync(chain, {
        r = r, g = g, b = b, a = alpha,
        desat = chain.wantDesat, shown = tex:IsShown(), noMod = dim,
    })
    chain.boost:SetTexCoord(tex:GetTexCoord())
end

-- The base is always drawn desaturated while it wears a look (the ramp supplies the colour); what the tile asked for
-- (SetDesaturated(true) for a missing buff) is remembered and handed to the ramp.
local function ForceGrey(chain)
    chain.writing = true
    pcall(chain.base.SetDesaturated, chain.base, true)
    chain.writing = false
end

local function Release(chain)
    FS.IconStyle.Release(chain)
    chain.writing = true
    pcall(chain.base.SetDesaturated, chain.base, chain.wantDesat)
    chain.writing = false
end

-- Post-hooks on the texture's setters: the tile keeps driving its icon texture and the overlays follow.
local FOLLOW = { "SetVertexColor", "SetAlpha", "SetShown", "Show", "Hide", "SetTexCoord" }

local function Hook(chain)
    local tex = chain.base
    if type(hooksecurefunc) ~= "function" then return end
    for _, method in ipairs(FOLLOW) do
        if type(tex[method]) == "function" then
            pcall(hooksecurefunc, tex, method, function()
                if chain.active and not chain.writing then pcall(Mirror, chain) end
            end)
        end
    end
    if type(tex.SetDesaturated) == "function" then
        pcall(hooksecurefunc, tex, "SetDesaturated", function(_, flag)
            if chain.writing then return end
            chain.wantDesat = flag and true or false
            if chain.active then
                ForceGrey(chain)
                pcall(Mirror, chain)
            end
        end)
    end
    -- the tile replaced the icon with something else (the empty slot's colour): it is not a spell icon any more
    for _, method in ipairs({ "SetTexture", "SetColorTexture" }) do
        if type(tex[method]) == "function" then
            pcall(hooksecurefunc, tex, method, function()
                if chain.active and not chain.writing then pcall(Release, chain) end
            end)
        end
    end
end

local function ChainOf(tex)
    local chain = chains[tex]
    if chain then return chain end
    local IS = FS.IconStyle
    local parent = tex:GetParent()
    local layer, sub = tex:GetDrawLayer()
    local clamped = IS.ClampSublevel(sub)
    if clamped ~= sub then tex:SetDrawLayer(layer, clamped) end
    chain = IS.NewChain(tex, parent, layer, clamped)
    -- what the tile already asked for before it had a look
    chain.wantDesat = tex.IsDesaturated and tex:IsDesaturated() and true or false
    chains[tex] = chain
    Hook(chain)
    return chain
end

-- Textures that asked for a look in combat: the chain is not built in combat (creating, anchoring and layering regions of a
-- tile that may sit on a secure host), so they keep the stock icon until PLAYER_REGEN_ENABLED.
local deferred = setmetatable({}, { __mode = "k" })

local function InCombat()
    return type(InCombatLockdown) == "function" and InCombatLockdown() and true or false
end

-- Look runs inside the pcall too: nothing about the value or the setting can throw out of a bind or a repaint.
local function Draw(tex, stock)
    local look = SpellArt.Look(stock)
    local chain = chains[tex]
    if not look or not FS.IconStyle then
        deferred[tex] = nil
        if chain and chain.active then Release(chain) end
        tex:SetTexture(stock)
        return
    end
    if not chain then
        if InCombat() then
            deferred[tex] = true
            tex:SetTexture(stock)
            return
        end
        chain = ChainOf(tex)
    end
    deferred[tex] = nil
    chain.writing = true
    local ok, err = pcall(tex.SetTexture, tex, stock)
    chain.writing = false
    if not ok then error(err, 0) end
    if not FS.IconStyle.Dress(chain, stock, nil, look) then
        tex:SetTexture(stock)
        return
    end
    ForceGrey(chain)
    Mirror(chain)
end

local function Write(tex, stock)
    pcall(Draw, tex, stock)
end

-- Draws `stock` on `tex` in the current style and remembers it for a later repaint.
function SpellArt.Set(tex, stock)
    bound[tex] = stock
    Write(tex, stock)
end

function SpellArt.Repaint()
    for tex, stock in pairs(bound) do Write(tex, stock) end
end

if FS.Config and FS.Config.OnChange then
    FS.Config.OnChange(SpellArt.SETTING.key, SpellArt.Repaint)
end

-- Out of combat again: build the chains that were asked for in combat.
if type(CreateFrame) == "function" then
    local events = CreateFrame("Frame")
    pcall(events.RegisterEvent, events, "PLAYER_REGEN_ENABLED")
    events:SetScript("OnEvent", function()
        for tex in pairs(deferred) do
            deferred[tex] = nil
            local stock = bound[tex]
            if stock ~= nil then Write(tex, stock) end
        end
    end)
end
